<?php
function grocery_api_action(PDO $pdo,string $action,int $companyId,array $user,array $d):void{
    $dateOk=static fn($v)=>is_string($v)&&preg_match('/^\d{4}-\d{2}-\d{2}$/',$v)&&DateTime::createFromFormat('!Y-m-d',$v)!==false;
    if($action==='grocery-company-profile'){$q=$pdo->prepare('SELECT trade_name,address,contact_number FROM companies WHERE id=?');$q->execute([$companyId]);$profile=$q->fetch();if(!$profile)throw new RuntimeException('Shop profile not found.');out($profile);}
    if($action==='grocery-overview'){
        $q=$pdo->prepare('SELECT COUNT(*) products,COALESCE(SUM(current_stock),0) units,COALESCE(SUM(current_stock*cost_price),0) stock_cost,SUM(CASE WHEN current_stock<=minimum_stock THEN 1 ELSE 0 END) low_stock,SUM(CASE WHEN expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 90 DAY) THEN 1 ELSE 0 END) expiring FROM grocery_products WHERE company_id=? AND is_active=1');$q->execute([$companyId]);$s=$q->fetch()?:[];
        $q=$pdo->prepare('SELECT COUNT(*) bills,COALESCE(SUM(total_amount),0) total,COALESCE(SUM(vat_amount),0) vat FROM grocery_sales WHERE company_id=? AND sale_date=CURDATE()');$q->execute([$companyId]);$s['today_sales']=$q->fetch()?:[];
        $q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) total FROM grocery_purchases WHERE company_id=? AND purchase_date=CURDATE()');$q->execute([$companyId]);$s['today_purchases']=(float)$q->fetchColumn();
        $q=$pdo->prepare('SELECT COALESCE(SUM(balance_amount),0) balance FROM grocery_sales WHERE company_id=?');$q->execute([$companyId]);$s['customer_balance']=(float)$q->fetchColumn();
        $q=$pdo->prepare('SELECT p.id,p.product_code,p.product_name,p.category,p.current_stock,p.minimum_stock,p.unit_name,p.expiry_date FROM grocery_products p WHERE p.company_id=? AND p.is_active=1 AND (p.current_stock<=p.minimum_stock OR p.expiry_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 90 DAY)) ORDER BY (p.expiry_date IS NULL),p.expiry_date,p.product_name LIMIT 10');$q->execute([$companyId]);$s['alerts']=$q->fetchAll();out($s);
    }
    if($action==='grocery-products'){$q=$pdo->prepare('SELECT * FROM grocery_products WHERE company_id=? ORDER BY is_active DESC,product_name');$q->execute([$companyId]);out($q->fetchAll());}
    if($action==='grocery-customers'){$q=$pdo->prepare('SELECT c.*,COALESCE(x.balance,0) outstanding FROM grocery_customers c LEFT JOIN (SELECT customer_id,SUM(balance_amount) balance FROM grocery_sales WHERE company_id=? AND customer_id IS NOT NULL GROUP BY customer_id) x ON x.customer_id=c.id WHERE c.company_id=? ORDER BY c.customer_name');$q->execute([$companyId,$companyId]);out($q->fetchAll());}
    if($action==='grocery-suppliers'){$q=$pdo->prepare('SELECT s.*,COALESCE(x.balance,0) outstanding FROM grocery_suppliers s LEFT JOIN (SELECT supplier_id,SUM(balance_amount) balance FROM grocery_purchases WHERE company_id=? GROUP BY supplier_id) x ON x.supplier_id=s.id WHERE s.company_id=? ORDER BY s.supplier_name');$q->execute([$companyId,$companyId]);out($q->fetchAll());}
    if($action==='grocery-sales'||$action==='grocery-purchases'){$sales=$action==='grocery-sales';$head=$sales?'grocery_sales':'grocery_purchases';$line=$sales?'grocery_sale_items':'grocery_purchase_items';$join=$sales?'LEFT JOIN grocery_customers p ON p.id=h.customer_id AND p.company_id=h.company_id':'JOIN grocery_suppliers p ON p.id=h.supplier_id AND p.company_id=h.company_id';$person=$sales?'p.customer_name person_name,p.mobile person_mobile,COALESCE(NULLIF(p.building_flat,""),p.address) person_address':'p.supplier_name person_name';$number=$sales?'bill_number':'purchase_number';$date=$sales?'sale_date':'purchase_date';$q=$pdo->prepare("SELECT h.*,$person FROM $head h $join WHERE h.company_id=? ORDER BY h.$date DESC,h.id DESC LIMIT 200");$q->execute([$companyId]);$rows=$q->fetchAll();$iq=$pdo->prepare("SELECT ".($sales?'product_id,':'')."product_name,barcode,unit_name,quantity,".($sales?'unit_price,unit_cost':'unit_cost').",vat_rate,vat_amount,line_total".($sales?'':' ,expiry_date')." FROM $line WHERE company_id=? AND ".($sales?'sale_id':'purchase_id')."=? ORDER BY id");foreach($rows as &$row){$iq->execute([$companyId,$row['id']]);$row['items']=$iq->fetchAll();}unset($row);out($rows);}
    if($action==='grocery-daybook'){$from=trim($_GET['from']??date('Y-m-01'));$to=trim($_GET['to']??date('Y-m-d'));if(!$dateOk($from)||!$dateOk($to)||$from>$to)throw new RuntimeException('Choose a valid date range.');$sql='SELECT entry_date,reference,description,credit_amount,debit_amount,payment_method FROM (SELECT s.sale_date entry_date,s.bill_number reference,CONCAT("Sale · ",COALESCE(c.customer_name,"Counter sale")) description,CASE WHEN s.payment_mode="Cash" THEN s.amount_paid ELSE 0 END credit_amount,0 debit_amount,COALESCE(s.payment_method,s.payment_mode) payment_method FROM grocery_sales s LEFT JOIN grocery_customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE s.company_id=? UNION ALL SELECT p.purchase_date,p.purchase_number,CONCAT("Purchase · ",s.supplier_name),0,p.amount_paid,COALESCE(p.payment_method,p.payment_mode) FROM grocery_purchases p JOIN grocery_suppliers s ON s.id=p.supplier_id AND s.company_id=p.company_id WHERE p.company_id=? AND p.payment_mode="Cash" UNION ALL SELECT x.payment_date,CONCAT("GCR-",LPAD(x.id,6,"0")),CONCAT("Customer payment · ",s.bill_number," · ",c.customer_name),x.amount,0,x.payment_method FROM grocery_customer_payments x JOIN grocery_sales s ON s.id=x.sale_id AND s.company_id=x.company_id JOIN grocery_customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE x.company_id=? UNION ALL SELECT x.payment_date,CONCAT("GSP-",LPAD(x.id,6,"0")),CONCAT("Supplier payment · ",p.purchase_number," · ",s.supplier_name),0,x.amount,x.payment_method FROM grocery_supplier_payments x JOIN grocery_purchases p ON p.id=x.purchase_id AND p.company_id=x.company_id JOIN grocery_suppliers s ON s.id=p.supplier_id AND s.company_id=p.company_id WHERE x.company_id=? UNION ALL SELECT e.expense_date,CONCAT("GE-",LPAD(e.id,6,"0")),CONCAT("Expense · ",e.expense_name),0,e.amount,e.payment_method FROM grocery_expenses e WHERE e.company_id=?) x WHERE entry_date BETWEEN ? AND ? ORDER BY entry_date DESC,reference DESC';$q=$pdo->prepare($sql);$q->execute([$companyId,$companyId,$companyId,$companyId,$companyId,$from,$to]);out(['from'=>$from,'to'=>$to,'rows'=>$q->fetchAll()]);}
    if($action==='grocery-customer-wallet'){$q=$pdo->prepare('SELECT s.id,s.bill_number,s.sale_date,s.total_amount,s.amount_paid,s.balance_amount,s.customer_id,c.customer_name,c.mobile FROM grocery_sales s JOIN grocery_customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE s.company_id=? AND s.payment_mode="Credit" AND s.balance_amount>0 ORDER BY s.sale_date,s.id');$q->execute([$companyId]);$bills=$q->fetchAll();$q=$pdo->prepare('SELECT p.id,p.payment_date,p.amount,p.payment_method,p.reference,s.bill_number,c.customer_name FROM grocery_customer_payments p JOIN grocery_sales s ON s.id=p.sale_id AND s.company_id=p.company_id JOIN grocery_customers c ON c.id=s.customer_id AND c.company_id=s.company_id WHERE p.company_id=? ORDER BY p.payment_date DESC,p.id DESC LIMIT 300');$q->execute([$companyId]);out(['bills'=>$bills,'payments'=>$q->fetchAll()]);}
    if($action==='grocery-supplier-wallet'){$q=$pdo->prepare('SELECT p.id,p.purchase_number,p.purchase_date,p.due_date,p.total_amount,p.amount_paid,p.balance_amount,p.supplier_id,s.supplier_name,s.mobile FROM grocery_purchases p JOIN grocery_suppliers s ON s.id=p.supplier_id AND s.company_id=p.company_id WHERE p.company_id=? AND p.balance_amount>0 ORDER BY p.purchase_date,p.id');$q->execute([$companyId]);$bills=$q->fetchAll();$q=$pdo->prepare('SELECT x.id,x.payment_date,x.amount,x.payment_method,x.reference,p.purchase_number,s.supplier_name FROM grocery_supplier_payments x JOIN grocery_purchases p ON p.id=x.purchase_id AND p.company_id=x.company_id JOIN grocery_suppliers s ON s.id=p.supplier_id AND s.company_id=p.company_id WHERE x.company_id=? ORDER BY x.payment_date DESC,x.id DESC LIMIT 300');$q->execute([$companyId]);out(['bills'=>$bills,'payments'=>$q->fetchAll()]);}    if($action==='grocery-expenses'){$q=$pdo->prepare('SELECT * FROM grocery_expenses WHERE company_id=? ORDER BY expense_date DESC,id DESC LIMIT 500');$q->execute([$companyId]);out($q->fetchAll());}
    if($action==='grocery-reports'){$from=trim($_GET['from']??date('Y-m-01'));$to=trim($_GET['to']??date('Y-m-d'));if(!$dateOk($from)||!$dateOk($to)||$from>$to)throw new RuntimeException('Choose a valid date range.');$q=$pdo->prepare('SELECT COUNT(*) bill_count,COALESCE(SUM(subtotal_amount),0) subtotal,COALESCE(SUM(vat_amount),0) vat,COALESCE(SUM(discount_amount),0) discount,COALESCE(SUM(total_amount),0) sales,COALESCE(SUM(balance_amount),0) receivable FROM grocery_sales WHERE company_id=? AND sale_date BETWEEN ? AND ?');$q->execute([$companyId,$from,$to]);$summary=$q->fetch();$q=$pdo->prepare('SELECT COALESCE(SUM(total_amount),0) purchases,COALESCE(SUM(vat_amount),0) input_vat FROM grocery_purchases WHERE company_id=? AND purchase_date BETWEEN ? AND ?');$q->execute([$companyId,$from,$to]);$purchase=$q->fetch();$q=$pdo->prepare('SELECT COALESCE(SUM(amount),0) expenses FROM grocery_expenses WHERE company_id=? AND expense_date BETWEEN ? AND ?');$q->execute([$companyId,$from,$to]);$summary['expenses']=(float)$q->fetchColumn();$summary['purchases']=(float)$purchase['purchases'];$summary['input_vat']=(float)$purchase['input_vat'];$q=$pdo->prepare('SELECT COALESCE(SUM(i.quantity*(i.unit_price-i.unit_cost)),0) gross_profit FROM grocery_sale_items i JOIN grocery_sales s ON s.id=i.sale_id AND s.company_id=i.company_id WHERE i.company_id=? AND s.sale_date BETWEEN ? AND ?');$q->execute([$companyId,$from,$to]);$summary['gross_profit']=(float)$q->fetchColumn();$summary['net_profit']=$summary['gross_profit']-$summary['expenses'];$q=$pdo->prepare('SELECT product_name,category,current_stock,minimum_stock,unit_name,expiry_date,cost_price,sale_price FROM grocery_products WHERE company_id=? AND is_active=1 ORDER BY CASE WHEN current_stock<=minimum_stock THEN 0 ELSE 1 END,product_name');$q->execute([$companyId]);$products=$q->fetchAll();out(['from'=>$from,'to'=>$to,'summary'=>$summary,'products'=>$products]);}
    if($action==='grocery-product-save'){
        $id=(int)($d['id']??0);$name=trim($d['product_name']??'');$category=trim($d['category']??'General');$unit=trim($d['unit_name']??'Piece');$barcode=trim($d['barcode']??'');$code=trim($d['product_code']??'');$brand=trim($d['brand']??'');$description=trim($d['description']??'');$cost=round((float)($d['cost_price']??0),2);$sale=round((float)($d['sale_price']??0),2);$vat=round((float)($d['vat_rate']??5),2);$stock=round((float)($d['current_stock']??0),3);$minimum=round((float)($d['minimum_stock']??0),3);$expiry=trim($d['expiry_date']??'');if($name===''||$category===''||$cost<0||$sale<0||$vat<0||$vat>100||$stock<0||$minimum<0||!in_array($unit,['Piece','Kg','Gram','Litre','Millilitre','Pack','Box','Carton','Bottle','Dozen','Other'],true)||($expiry!==''&&!$dateOk($expiry)))throw new RuntimeException('Enter valid product details, prices, quantity, and VAT.');if($barcode!==''){$q=$pdo->prepare('SELECT id FROM grocery_products WHERE company_id=? AND barcode=? AND id<>?');$q->execute([$companyId,$barcode,$id]);if($q->fetch())throw new RuntimeException('This barcode is already used by another product.');}
        if($id){$q=$pdo->prepare('UPDATE grocery_products SET product_name=?,category=?,brand=?,unit_name=?,description=?,cost_price=?,sale_price=?,vat_rate=?,current_stock=?,minimum_stock=?,expiry_date=?,barcode=?,is_active=? WHERE id=? AND company_id=?');$q->execute([$name,$category,$brand?:null,$unit,$description?:null,$cost,$sale,$vat,$stock,$minimum,$expiry?:null,$barcode?:null,!empty($d['is_active'])?1:0,$id,$companyId]);if(!$q->rowCount()){$q=$pdo->prepare('SELECT id FROM grocery_products WHERE id=? AND company_id=?');$q->execute([$id,$companyId]);if(!$q->fetch())throw new RuntimeException('Product not found in this company.');}out(['id'=>$id,'product_name'=>$name]);}
        $pdo->beginTransaction();try{$pdo->query('SELECT id FROM companies WHERE id='.(int)$companyId.' FOR UPDATE');if($code===''){$q=$pdo->prepare('SELECT COALESCE(MAX(CAST(SUBSTRING(product_code,4) AS UNSIGNED)),0)+1 FROM grocery_products WHERE company_id=? AND product_code LIKE "GR-%"');$q->execute([$companyId]);$code='GR-'.str_pad((string)$q->fetchColumn(),5,'0',STR_PAD_LEFT);}$q=$pdo->prepare('INSERT INTO grocery_products(company_id,product_code,barcode,product_name,category,brand,unit_name,description,cost_price,sale_price,vat_rate,current_stock,minimum_stock,expiry_date,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$companyId,$code,$barcode?:null,$name,$category,$brand?:null,$unit,$description?:null,$cost,$sale,$vat,$stock,$minimum,$expiry?:null,$user['id']]);$id=(int)$pdo->lastInsertId();$pdo->commit();out(['id'=>$id,'product_code'=>$code]);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}
    }
    if($action==='grocery-customer-save'||$action==='grocery-supplier-save'){$customer=$action==='grocery-customer-save';$id=(int)($d['id']??0);$name=trim($d[$customer?'customer_name':'supplier_name']??'');$mobile=preg_replace('/\s+/',' ',trim($d['mobile']??''));$email=trim($d['email']??'');$trn=trim($d['trn']??'');$address=trim($d['address']??'');$buildingFlat=trim($d['building_flat']??'');$notes=trim($d['notes']??'');if($name===''||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))||($mobile!==''&&!preg_match('/^[0-9+() .-]{5,30}$/',$mobile)))throw new RuntimeException('Enter a valid name and contact details.');if($customer){$person=trim($d['contact_person']??'');$table='grocery_customers';$sql='UPDATE grocery_customers SET customer_name=?,building_flat=?,mobile=?,email=?,trn=?,address=?,notes=? WHERE id=? AND company_id=?';$values=[$name,$buildingFlat?:null,$mobile?:null,$email?:null,$trn?:null,$address?:null,$notes?:null];$insert='INSERT INTO grocery_customers(company_id,customer_name,building_flat,mobile,email,trn,address,notes) VALUES(?,?,?,?,?,?,?,?)';$insertValues=[$companyId,$name,$buildingFlat?:null,$mobile?:null,$email?:null,$trn?:null,$address?:null,$notes?:null];}else{$person=trim($d['contact_person']??'');$table='grocery_suppliers';$sql='UPDATE grocery_suppliers SET supplier_name=?,contact_person=?,mobile=?,email=?,trn=?,address=?,notes=? WHERE id=? AND company_id=?';$values=[$name,$person?:null,$mobile?:null,$email?:null,$trn?:null,$address?:null,$notes?:null];$insert='INSERT INTO grocery_suppliers(company_id,supplier_name,contact_person,mobile,email,trn,address,notes) VALUES(?,?,?,?,?,?,?,?)';$insertValues=[$companyId,$name,$person?:null,$mobile?:null,$email?:null,$trn?:null,$address?:null,$notes?:null];}if($id){$q=$pdo->prepare($sql);$q->execute([...$values,$id,$companyId]);out(['id'=>$id,'name'=>$name]);}$q=$pdo->prepare($insert);$q->execute($insertValues);out(['id'=>$pdo->lastInsertId(),'name'=>$name]);}
    if($action==='grocery-sale-save'){
        $items=$d['items']??[];$customerId=(int)($d['customer_id']??0);$saleDate=trim($d['sale_date']??date('Y-m-d'));$discount=round((float)($d['discount_amount']??0),2);$vatMode=$d['vat_mode']??'Inclusive';$mode=$d['payment_mode']??'Cash';$method=$d['payment_method']??'Cash';$paidInput=$d['amount_paid']??null;$note=trim($d['notes']??'');if(!is_array($items)||!count($items)||!$dateOk($saleDate)||$discount<0||!in_array($vatMode,['Inclusive','Exclusive'],true)||!in_array($mode,['Cash','Credit'],true))throw new RuntimeException('Add sale items and check the sale date, discount, and payment mode.');if($mode==='Cash'&&!in_array($method,['Cash','Card','Bank','Cheque','Tabby','Tamara'],true))throw new RuntimeException('Choose a valid payment method.');if($mode==='Credit'&&$customerId<=0)throw new RuntimeException('Select a customer for a credit sale.');if($customerId){$q=$pdo->prepare('SELECT id FROM grocery_customers WHERE id=? AND company_id=?');$q->execute([$customerId,$companyId]);if(!$q->fetch())throw new RuntimeException('Select a customer saved for this company.');}
        $pdo->beginTransaction();try{$q=$pdo->prepare('SELECT id FROM companies WHERE id=? FOR UPDATE');$q->execute([$companyId]);$subtotal=0;$vatAmount=0;$clean=[];foreach($items as $line){$pid=(int)($line['product_id']??0);$qty=round((float)($line['quantity']??0),3);if($pid<=0||$qty<=0)throw new RuntimeException('Choose a product and enter a quantity greater than zero.');$q=$pdo->prepare('SELECT * FROM grocery_products WHERE id=? AND company_id=? AND is_active=1 FOR UPDATE');$q->execute([$pid,$companyId]);$p=$q->fetch();if(!$p)throw new RuntimeException('A selected product is unavailable. Refresh the product list.');if((float)$p['current_stock']<$qty)throw new RuntimeException('Not enough stock for '.$p['product_name'].' (available '.$p['current_stock'].' '.$p['unit_name'].').');$price=round((float)($line['unit_price']??$p['sale_price']),2);if($price<0)throw new RuntimeException('Sale price cannot be negative.');$entered=round($price*$qty,2);$rate=(float)$p['vat_rate'];if($vatMode==='Inclusive'&&$rate>0){$lineVat=round($entered*$rate/(100+$rate),2);$base=round($entered-$lineVat,2);$total=$entered;}else{$base=$entered;$lineVat=round($base*$rate/100,2);$total=round($base+$lineVat,2);}$subtotal+=$base;$vatAmount+=$lineVat;$clean[]=[$p,$qty,$price,$base,$lineVat,$total];$q=$pdo->prepare('UPDATE grocery_products SET current_stock=current_stock-? WHERE id=? AND company_id=? AND current_stock>=?');$q->execute([$qty,$pid,$companyId,$qty]);if(!$q->rowCount())throw new RuntimeException('Stock changed while saving. Refresh and try again.');}
        $subtotal=round($subtotal,2);$vatAmount=round($vatAmount,2);$totalAmount=round($subtotal+$vatAmount-$discount,2);if($discount>$subtotal+$vatAmount)throw new RuntimeException('Discount cannot exceed the sale total.');$paid=$paidInput===null?($mode==='Cash'?$totalAmount:0):round((float)$paidInput,2);if($paid<0||$paid>$totalAmount)throw new RuntimeException('Amount paid must be from zero up to the bill total.');$balance=round($totalAmount-$paid,2);if($mode==='Cash'&&$balance>0.009)throw new RuntimeException('A cash sale must be paid in full. Choose Credit for an unpaid balance.');if($mode==='Credit')$method=null;$q=$pdo->prepare('SELECT COALESCE(MAX(CAST(SUBSTRING(bill_number,4) AS UNSIGNED)),0)+1 FROM grocery_sales WHERE company_id=? AND bill_number LIKE "GS-%"');$q->execute([$companyId]);$bill='GS-'.str_pad((string)$q->fetchColumn(),6,'0',STR_PAD_LEFT);$q=$pdo->prepare('INSERT INTO grocery_sales(company_id,bill_number,sale_date,customer_id,subtotal_amount,vat_amount,vat_mode,discount_amount,total_amount,amount_paid,balance_amount,payment_mode,payment_method,payment_reference,notes,created_by) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');$q->execute([$companyId,$bill,$saleDate,$customerId?:null,$subtotal,$vatAmount,$vatMode,$discount,$totalAmount,$paid,$balance,$mode,$method?:null,trim($d['payment_reference']??'')?:null,$note?:null,$user['id']]);$saleId=(int)$pdo->lastInsertId();$iq=$pdo->prepare('INSERT INTO grocery_sale_items(company_id,sale_id,product_id,product_name,barcode,unit_name,quantity,unit_price,unit_cost,vat_rate,vat_amount,line_total) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)');foreach($clean as [$p,$qty,$price,$base,$lineVat,$lineTotal])$iq->execute([$companyId,$saleId,$p['id'],$p['product_name'],$p['barcode'],$p['unit_name'],$qty,$price,$p['cost_price'],$p['vat_rate'],$lineVat,$lineTotal]);$pdo->commit();out(['id'=>$saleId,'bill_number'=>$bill,'total_amount'=>$totalAmount,'vat_amount'=>$vatAmount,'balance_amount'=>$balance]);}catch(Throwable $e){if($pdo->in