    }
    if($action==='grocery-sale-update'){
        $id=(int)($d['sale_id']??0);$items=$d['items']??[];$customerId=(int)($d['customer_id']??0);$saleDate=trim($d['sale_date']??'');$discount=round((float)($d['discount_amount']??0),2);$vatMode=$d['vat_mode']??'Exclusive';$mode=$d['payment_mode']??'';$method=$d['payment_method']??'Cash';
        if($id<=0||!is_array($items)||!count($items)||!$dateOk($saleDate)||$discount<0||!in_array($vatMode,['Inclusive','Exclusive'],true)||!in_array($mode,['Cash','Credit'],true))throw new RuntimeException('Check the bill date, items, discount, and payment mode.');
        if($mode==='Cash'&&!in_array($method,['Cash','Card','Bank','Cheque','Tabby','Tamara'],true))throw new RuntimeException('Choose a valid payment method.');
        if($mode==='Credit'&&$customerId<=0)throw new RuntimeException('Select a customer for a credit sale.');
        if($customerId){$q=$pdo->prepare('SELECT id FROM grocery_customers WHERE id=? AND company_id=?');$q->execute([$customerId,$companyId]);if(!$q->fetch())throw new RuntimeException('Select a customer saved for this company.');}
        $pdo->beginTransaction();try{
            $q=$pdo->prepare('SELECT * FROM grocery_sales WHERE id=? AND company_id=? FOR UPDATE');$q->execute([$id,$companyId]);$sale=$q->fetch();if(!$sale)throw new RuntimeException('Sale bill not found. Refresh and try again.');
            if($mode!==$sale['payment_mode'])throw new RuntimeException('Payment mode cannot be changed while editing a saved bill.');
